const BAREWORD = /[A-Za-z0-9_-]/

/** A cursor over a single line of the document. Lines never span newlines. */
export class LineCursor {
  constructor(text) {
    this.s = text
    this.i = 0
  }

  eof() {
    return this.i >= this.s.length
  }

  peek() {
    return this.s[this.i]
  }

  /** Skips spaces and tabs only; leaves comments alone. */
  skipSpacesTabs() {
    while (!this.eof() && (this.s[this.i] === ' ' || this.s[this.i] === '\t')) this.i++
  }

  /**
   * Skips spaces and tabs, then treats a `#` or `;` that follows as the
   * start of a comment and jumps straight to the end of the line.
   */
  skipWs() {
    this.skipSpacesTabs()
    if (!this.eof() && (this.s[this.i] === '#' || this.s[this.i] === ';')) {
      this.i = this.s.length
    }
  }
}

/** Reads a `"`-delimited basic string, decoding its escapes. */
export function parseBasicString(lp) {
  lp.i++ // opening quote
  let out = ''
  for (;;) {
    if (lp.eof()) throw new ParseError('unterminated string')
    const c = lp.s[lp.i]
    if (c === '"') {
      lp.i++
      return out
    }
    if (c === '\\') {
      lp.i++
      if (lp.eof()) throw new ParseError('unterminated string')
      const e = lp.s[lp.i]
      if (e === '"') { out += '"'; lp.i++ }
      else if (e === '\\') { out += '\\'; lp.i++ }
      else if (e === 'n') { out += '\n'; lp.i++ }
      else if (e === 't') { out += '\t'; lp.i++ }
      else if (e === 'r') { out += '\r'; lp.i++ }
      else if (e === '0') { out += '\0'; lp.i++ }
      else if (e === 'u') {
        lp.i++
        const hex = lp.s.slice(lp.i, lp.i + 4)
        if (hex.length === 4 && /^[0-9a-fA-F]{4}$/.test(hex)) {
          out += String.fromCharCode(parseInt(hex, 16))
          lp.i += 4
        } else {
          throw new ParseError('invalid escape \\u')
        }
      } else {
        throw new ParseError(`invalid escape \\${e}`)
      }
    } else {
      out += c
      lp.i++
    }
  }
