/** Reads a `'`-delimited literal string; no escapes are recognized. */
export function parseLiteralString(lp) {
  lp.i++ // opening quote
  let out = ''
  for (;;) {
    if (lp.eof()) throw new ParseError('unterminated string')
    const c = lp.s[lp.i]
    if (c === "'") {
      lp.i++
      return out
    }
    out += c
    lp.i++
  }
