{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e12-self-review-sonnet-t5t6-20260927T000002Z/cell-sCecvp/src/nodes.js","content":"/**
 * The in-memory tree the parser builds. Every node has a `kind`:
 * `table`, `aot` (array of tables), `array`, `string`, `integer`, `float`
 * or `boolean`. Tables keep an insertion-order `Map` (output always sorts
 * keys itself, so insertion order is only a convenience) plus a `locked`
 * flag set once a `[name]` header has named that exact table, so a second
 * such header on it is rejected.
 */

export function newTable() {
  return { kind: 'table', map: new Map(), locked: false }
}

export function newArrayOfTables() {
  return { kind: 'aot', items: [] }
}

export function newArray(items) {
  return { kind: 'array', items }
}

export function joinKey(prefix, key) {
  return prefix === '' ? key : `${prefix}.${key}`
}

export function joinIndex(prefix, index) {
  return `${prefix}[${index}]`
}
"}

