import { parseDottedName } from './lexer.js'
import { newTable, newArrayOfTables, joinKey } from './nodes.js'

/** Parses a `[name]` or `[[name]]` header line. `lp` is positioned at `[`. */
export function parseHeaderLine(lp) {
  lp.i++ // first '['
  let isArray = false
  if (!lp.eof() && lp.peek() === '[') {
    isArray = true
    lp.i++
  }
  lp.skipSpacesTabs()
  const names = parseDottedName(lp, 'unterminated table header')
  lp.skipSpacesTabs()
  if (lp.eof() || lp.peek() !== ']') throw new ParseError('unterminated table header')
  lp.i++
  if (isArray) {
    if (lp.eof() || lp.peek() !== ']') throw new ParseError('unterminated table header')
    lp.i++
  }
  lp.skipWs()
  if (!lp.eof()) throw new ParseError('trailing text after a table header')
  return { isArray, names }
}

/** Applies a parsed header, updating `state.currentTable`/`currentPath`. */
export function applyHeader(root, state, header) {
  const { isArray, names } = header
  let node = root
  let path = ''
  for (let k = 0; k < names.length - 1; k++) {
    const name = names[k]
    path = joinKey(path, name)
    if (node.map.has(name)) {
      const existing = node.map.get(name)
      if (existing.kind === 'table') {
        node = existing
      } else if (existing.kind === 'aot') {
        node = existing.items[existing.items.length - 1]
      } else {
        throw new ParseError(`${path} is not a table`)
      }
    } else {
      const t = newTable()
      node.map.set(name, t)
      node = t
    }
  }
  const last = names[names.length - 1]
  const fullPath = joinKey(path, last)

  if (!isArray) {
    if (node.map.has(last)) {
      const existing = node.map.get(last)
      if (existing.kind !== 'table') throw new ParseError(`${fullPath} is not a table`)
      if (existing.locked) throw new ParseError(`table ${fullPath} is defined twice`)
      existing.locked = true
      state.currentTable = existing
    } else {
      const t = newTable()
      t.locked = true
      node.map.set(last, t)
      state.currentTable = t
    }
  } else {
    let aot
    if (node.map.has(last)) {
      aot = node.map.get(last)
      if (aot.kind !== 'aot') throw new ParseError(`${fullPath} is not an array of tables`)
    } else {
      aot = newArrayOfTables()
      node.map.set(last, aot)
    }
    const t = newTable()
    aot.items.push(t)
    state.currentTable = t
  }
  state.currentPath = fullPath
}
